    printf("%d %d %d\n", MON, TUE, WED);   /* 0 5 6 */
    printf("%d\n", 'A');                   /* 65: char constant is an int */
    printf("%c\n", 'A' + 1);               /* B */
    printf("%d\n", 010 + 0x10);            /* 8 + 16 = 24 (octal + hex) */
    return 0;
}

#include <stdio.h>
int calls;                      /* global: zero-initialised */
void visit(void) {
    static int total = 100;     /* initialised only once */
    int local = 100;            /* re-created on every call */
    total += 10;
    local += 10;
    calls++;
    printf("%d %d %d\n", calls, total, local);
}
int main(void) {
    visit(); visit(); visit();
    return 0;
}

