#include <stdio.h>
int main(void) {
    int a = 0, b = 2, c = 3, r;
    r = a++ && b++;            /* a++ yields 0, so b++ is skipped */
    printf("%d %d %d\n", a, b, r);
    r = a++ || ++c;            /* a++ yields 1, so ++c is skipped */
    printf("%d %d %d\n", a, c, r);
    r = (b > c) ? b-- : c--;   /* only the chosen branch runs */
    printf("%d %d %d\n", b, c, r);
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 11;                    /* binary 1011 */
    int p = x & 4 != 0;            /* parsed as x & (4 != 0) */
    int q = x >> 1 + 1;            /* parsed as x >> (1 + 1) */
    unsigned u = 1;
    int big = -2 > u;              /* -2 is converted to unsigned */
    double d = x / 2 + x % 2 * 0.5;
    printf("%d %d %d %.1f\n", p, q, big, d);
    return 0;
}

