int add(int a, int b) {         /* 2. definition: a, b are the parameters */
    return a + b;               /* return ends the function */
}

void swapV(int a, int b) { int t = a; a = b; b = t; }        /* works on copies */
void swapP(int *a, int *b) { int t = *a; *a = *b; *b = t; }   /* works via addresses */

int main(void) {
    int x = 1, y = 2;
    swapV(x, y);   printf("%d %d\n", x, y);   /* 1 2: unchanged */
    swapP(&x, &y); printf("%d %d\n", x, y);   /* 2 1: swapped   */
    return 0;
}

int counter(void) {
    static int calls = 0;   /* initialised once, lives for the whole run */
    int temp = 0;           /* auto: recreated on every call */
    calls++; temp++;
    return calls;
}
int main(void) {
    counter(); counter();
    printf("%d\n", counter());   /* 3  (temp would be 1 on every call) */
    return 0;
}

void show(int n) {
    if (n == 0) return;        /* base case */
    printf("%d ", n);          /* printed on the way down: 3 2 1 */
    show(n - 1);
    printf("%d ", n);          /* printed while unwinding: 1 2 3 */
}
/* show(3) prints: 3 2 1 1 2 3 */
int sum(int n) { return n ? n + sum(n - 1) : 0; }   /* sum(5) = 15 */
void rev(int n) { if (n) { printf("%d", n % 10); rev(n / 10); } }  /* 123 -> 321 */

