int my_strlen(const char *s) {          /* count until '\0' */
    int n = 0;
    while (s[n] != '\0') n++;
    return n;
}
void reverse(char *s) {                 /* portable strrev */
    for (int i = 0, j = my_strlen(s) - 1; i < j; i++, j--) {
        char t = s[i]; s[i] = s[j]; s[j] = t;
    }
}
int is_palindrome(const char *s) {      /* "level" -> 1, "exam" -> 0 */
    for (int i = 0, j = my_strlen(s) - 1; i < j; i++, j--)
        if (s[i] != s[j]) return 0;
    return 1;
}

